import { useState } from "react";

type CalendarItem =
  | { type: "empty"; key: string }
  | {
      type: "day";
      key: string;
      day: number;
      date: Date;
      isDisabled: boolean;
      isSelected: boolean;
    };

export function App() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [selectedTime, setSelectedTime] = useState<string | null>(null);

  const availableTimeSlots = ["10:00", "11:00", "14:00", "15:00", "16:00", "18:00"];

  const redirectToBank = (amount: string, comment: string) => {
    const recipientName = "Zsebeházi Andrea";
    const accountNumber = "107000314973750951100005";
    const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);

    if (isMobile) {
      const bankLink = `otpbank://payment?account=${accountNumber}&amount=${amount}&name=${encodeURIComponent(
        recipientName
      )}&message=${encodeURIComponent(comment)}`;
      window.location.href = bankLink;
    } else {
      alert(
        "Az automatikus átirányítás csak mobil eszközön működik. Kérjük, nyisd meg az oldalt a telefonodon."
      );
    }
  };

  const handlePurchase = () => {
    redirectToBank("10000", "Zsebibaba Kis Csomag");
  };

  const handleBookingConfirm = () => {
    if (!selectedDate || !selectedTime) return;

    const formattedDate = `${selectedDate.getFullYear()}.${String(selectedDate.getMonth() + 1).padStart(
      2,
      "0"
    )}.${String(selectedDate.getDate()).padStart(2, "0")}`;
    const comment = `Időpont: ${formattedDate} ${selectedTime}`;

    redirectToBank("25000", comment);
    setIsModalOpen(false);
  };

  const changeMonth = (delta: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(newDate.getMonth() + delta);
    setCurrentDate(newDate);
  };

  const getCalendarDays = (): CalendarItem[] => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDayOfMonth = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const firstDayIndex = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

    const days: CalendarItem[] = [];
    for (let i = 0; i < firstDayIndex; i += 1) {
      days.push({ type: "empty", key: `empty-${i}` });
    }

    const now = new Date();
    now.setHours(0, 0, 0, 0);

    for (let day = 1; day <= daysInMonth; day += 1) {
      const date = new Date(year, month, day);
      days.push({
        type: "day",
        key: `day-${day}`,
        day,
        date,
        isDisabled: date < now,
        isSelected: selectedDate?.toDateString() === date.toDateString(),
      });
    }

    return days;
  };

  const monthName = new Intl.DateTimeFormat("hu-HU", { month: "long" }).format(currentDate);
  const displayMonthYear = `${currentDate.getFullYear()}. ${monthName}`;

  return (
    <>
      <style>{`
        *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
        html { -webkit-text-size-adjust: 100%; -webkit-tap-highlight-color: transparent; }
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; -webkit-font-smoothing: antialiased; background: #000; color: #f5f5f7; overflow-x: hidden; position: relative; min-height: 100vh; }
        #bg-video { position: fixed; right: 0; bottom: 0; min-width: 100%; min-height: 100%; width: auto; height: auto; z-index: -100; object-fit: cover; filter: blur(12px) brightness(0.7); }
        header { position: absolute; top: 0; left: 0; right: 0; text-align: center; padding: 1.5rem 0; z-index: 10; display: flex; flex-direction: column; align-items: center; gap: 0.3rem; }
        h1 { font-size: 2.5rem; font-weight: 700; letter-spacing: -0.05em; color: #fff; }
        .container { min-height: 100vh; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 1rem; gap: 1rem; }
        .header-booking-btn { margin-top: 0.2rem; padding: 0.6rem 1.2rem !important; font-size: 0.9rem !important; }
        .glass-card { background: rgba(28, 28, 30, 0.75); backdrop-filter: blur(25px); -webkit-backdrop-filter: blur(25px); border-radius: 1.5rem; border: 1px solid rgba(255, 255, 255, 0.12); box-shadow: 0 16px 48px rgba(0, 0, 0, 0.3); width: 18rem; height: 18rem; padding: 1rem; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; transform: scale(0.49); margin-top: -5rem; margin-bottom: -5rem; }
        .glass-card h2 { font-size: 2.2rem; font-weight: 700; margin-bottom: 0.5rem; color: #fff; }
        .glass-card p { font-size: 1.6rem; font-weight: 600; color: #fff; margin-bottom: 1rem; }
        .button-primary, .button-secondary { border: none; cursor: pointer; transition: transform 0.2s, background-color 0.2s; font-size: 1rem; outline: none; -webkit-tap-highlight-color: transparent; touch-action: manipulation; font-weight: 500; border-radius: 9999px; color: #fff; }
        .button-primary { background: #0a84ff; padding: 0.875rem 1.75rem; }
        .button-primary:hover { transform: scale(1.05); background: #359aff; }
        .button-primary:active { transform: scale(0.98); }
        .button-primary:disabled { opacity: 0.5; cursor: not-allowed; transform: none; }
        .button-secondary { background: rgba(255, 255, 255, 0.15); padding: 0.8rem 1.8rem; font-size: 1.2rem; font-weight: 600; }
        .button-secondary:hover { transform: scale(1.05); background: rgba(255, 255, 255, 0.25); }
        .modal { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.5); display: flex; align-items: center; justify-content: center; padding: 1rem; z-index: 50; opacity: 0; visibility: hidden; transition: opacity 0.3s ease, visibility 0.3s ease; }
        .modal.active { opacity: 1; visibility: visible; }
        .modal-content { background: rgba(28, 28, 30, 0.75); backdrop-filter: blur(25px); -webkit-backdrop-filter: blur(25px); border-radius: 1.5rem; border: 1px solid rgba(255, 255, 255, 0.12); box-shadow: 0 16px 48px rgba(0, 0, 0, 0.3); width: 100%; max-width: 32rem; padding: 2rem; animation: modalFadeIn 0.3s ease forwards; }
        @keyframes modalFadeIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        .modal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.5rem; }
        .modal-header h3 { font-size: 1.5rem; font-weight: 700; }
        .close-btn { background: none; border: none; color: #8e8e93; cursor: pointer; font-size: 2rem; line-height: 1; padding: 0; width: 2rem; height: 2rem; display: flex; align-items: center; justify-content: center; transition: color 0.2s; outline: none; -webkit-tap-highlight-color: transparent; }
        .close-btn:hover { color: #fff; }
        .calendar-nav { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem; }
        .calendar-nav button { background: none; border: none; color: #f5f5f7; cursor: pointer; padding: 0.5rem; border-radius: 9999px; transition: background 0.2s; outline: none; -webkit-tap-highlight-color: transparent; }
        .calendar-nav button:hover { background: rgba(255, 255, 255, 0.1); }
        .calendar-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 0.5rem; }
        .weekday, .calendar-day { display: flex; justify-content: center; align-items: center; aspect-ratio: 1/1; }
        .weekday { font-weight: 500; font-size: 0.8rem; color: rgba(235, 235, 245, 0.6); }
        .calendar-day { cursor: pointer; border-radius: 9999px; transition: background-color 0.2s; outline: none; -webkit-tap-highlight-color: transparent; }
        .calendar-day.selected { background: #0a84ff; color: #fff; font-weight: 600; }
        .calendar-day.disabled { opacity: 0.35; cursor: not-allowed; pointer-events: none; }
        .time-slots-container { margin-top: 1.5rem; display: none; }
        .time-slots-container.active { display: block; }
        .time-slots { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.75rem; }
        .time-slot { cursor: pointer; border: 1px solid rgba(255, 255, 255, 0.2); text-align: center; padding: 0.5rem; border-radius: 0.5rem; transition: background-color 0.2s; }
        .time-slot.selected { background: #0a84ff; color: #fff; }
        .confirm-btn { width: 100%; margin-top: 2rem; }
        @media(min-width:640px) { h1 { font-size: 3rem; } }
      `}</style>
      <video autoPlay muted loop playsInline id="bg-video">
        <source src="" type="video/mp4" />
      </video>

      <header>
        <h1>Zsebibaba</h1>
        <button
