          <div className="modal-header">
            <h3>Időpontfoglalás</h3>
            <button className="close-btn" onClick={() => setIsModalOpen(false)}>
              ×
            </button>
          </div>
          <div>
            <div className="calendar-nav">
              <button onClick={() => changeMonth(-1)} aria-label="Előző hónap">
                <svg style={{ width: "1.5rem", height: "1.5rem" }} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" />
                </svg>
              </button>
              <h4>{displayMonthYear}</h4>
              <button onClick={() => changeMonth(1)} aria-label="Következő hónap">
                <svg style={{ width: "1.5rem", height: "1.5rem" }} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" />
                </svg>
              </button>
            </div>
            <div className="calendar-grid">
              <div className="weekday">H</div>
              <div className="weekday">K</div>
              <div className="weekday">Sze</div>
              <div className="weekday">Cs</div>
              <div className="weekday">P</div>
              <div className="weekday">Szo</div>
              <div className="weekday">V</div>
            </div>
            <div className="calendar-grid">
              {getCalendarDays().map((item) => {
                if (item.type === "empty") {
                  return <div key={item.key} className="calendar-day empty"></div>;
                }

                return (
                  <div
                    key={item.key}
                    className={`calendar-day ${item.isDisabled ? "disabled" : ""} ${
                      item.isSelected ? "selected" : ""
                    }`}
                    onClick={() => {
                      if (!item.isDisabled) {
                        setSelectedDate(item.date);
                        setSelectedTime(null);
                      }
                    }}
                  >
                    {item.day}
                  </div>
                );
              })}
            </div>
          </div>
          <div className={`time-slots-container ${selectedDate ? "active" : ""}`}>
            <h4>Válassz időpontot:</h4>
            <div className="time-slots">
              {availableTimeSlots.map((time) => (
                <div
                  key={time}
                  className={`time-slot ${selectedTime === time ? "selected" : ""}`}
                  onClick={() => setSelectedTime(time)}
                >
                  {time}
                </div>
              ))}
            </div>
          </div>
          <button
            className="button-primary confirm-btn"
            disabled={!selectedDate || !selectedTime}
            onClick={handleBookingConfirm}
          >
            Tovább az utaláshoz (25 000 Ft)
          </button>
        </div>
      </div>
    </>
  );
}

